console.log('✅ Login สำเร็จ\n');

const byCat = {};
for (const s of SUBJECTS) byCat[s.category] = (byCat[s.category] || 0) + 1;
console.log(`📚 รายวิชาทั้งหมด ${SUBJECTS.length} รายวิชา`);
for (const [cat, n] of Object.entries(byCat)) console.log(`   ${cat}: ${n} วิชา`);
console.log('');

let ok = 0, fail = 0;
for (const s of SUBJECTS) {
  try {
    await setDoc(doc(db, 'subjects', s.code), {
      code:            s.code,
      name:            s.name,
      nameEn:          s.nameEn          || '',
      credits:         s.credits         || '',
      category:        s.category,
      competencyGroup: s.competencyGroup,
      semester:        '',
      standardRef:     s.standardRef     || '',
      learningOutcome: s.learningOutcome || '',
      objectives:      s.objectives      || '',
      competencies:    s.competencies    || '',
      description:     s.description     || '',
      created_at:      new Date().toISOString(),
    });
    console.log(`  ✅ ${s.code}  ${s.name}`);
    ok++;
  } catch (err) {
    console.error(`  ❌ ${s.code}  ${err.message}`);
    fail++;
  }
}

console.log(`\n${'─'.repeat(55)}`);
console.log(`นำเข้าสำเร็จ ${ok} รายวิชา  |  ผิดพลาด ${fail} รายวิชา`);
process.exit(fail > 0 ? 1 : 0);
